$BackupDir = "C:\ollama\cvn_node\backups"; Clear-Host; Write-Host "====================================================================" -ForegroundColor Cyan; Write-Host "COVENANT STANDARD (CVN) - BLOCKCHAIN LEDGER BACKUP VALIDATOR" -ForegroundColor Cyan; Write-Host "====================================================================" -ForegroundColor Cyan; Write-Host ""; if (Test-Path -Path $BackupDir) { $BackupFiles = Get-ChildItem -Path $BackupDir -Filter "cvn_mainnet_backup_*.db" | Sort-Object LastWriteTime -Descending; if ($BackupFiles) { Write-Host "Found $($BackupFiles.Count) historical database snapshot vaults on disk." -ForegroundColor White; Write-Host "--------------------------------------------------------------------" -ForegroundColor Gray; foreach ($file in $BackupFiles) { $FileSizeKB = [math]::Round($file.Length / 1KB, 2); $Timestamp = $file.LastWriteTime.ToString("yyyy-MM-dd HH:mm:ss"); if ($file.Length -lt 4096) { Write-Host "CRITICAL WARNING: Snapshot [$($file.Name)] appears corrupted or empty! Size: $FileSizeKB KB" -ForegroundColor Red } else { Write-Host "VALIDATED: [$Timestamp] -> $($file.Name) ($FileSizeKB KB) [INTEGRITY PASS]" -ForegroundColor Green } } } else { Write-Host "Standby... Backup vault directory is currently empty." -ForegroundColor Yellow } } else { Write-Host "ERROR: Target backup directory path not found!" -ForegroundColor Red }; Write-Host "====================================================================" -ForegroundColor Cyan